<?php
require_once 'config.php'; requirePost();$user=requireRole('admin','supervisor');if($user['role']==='admin')$st=$pdo->query("SELECT id,expert_username,supervisor_username,approved_at,duration_minutes FROM rest_requests WHERE status='approved'");else{$st=$pdo->prepare("SELECT id,expert_username,supervisor_username,approved_at,duration_minutes FROM rest_requests WHERE status='approved' AND supervisor_username=?");$st->execute([$user['username']]);}$rows=$st->fetchAll();$insert=$pdo->prepare("INSERT INTO overtime_alerts(expert_username,supervisor_username,rest_request_id,overtime_seconds,alert_date,message,created_at) VALUES(?,?,?,?,CURDATE(),?,NOW()) ON DUPLICATE KEY UPDATE overtime_seconds=VALUES(overtime_seconds)");foreach($rows as $r){$over=time()-strtotime($r['approved_at'])-((int)$r['duration_minutes']*60);if($over>0)$insert->execute([$r['expert_username'],$r['supervisor_username'],$r['id'],$over,'استراحت از زمان مجاز عبور کرده است.']);}jsonResponse(['success'=>true]);
